    def _resolve_family_task_assignee(
        self,
        *,
        family: FamilyGroup,
        draft: dict[str, Any],
        approved_by: User,
    ) -> User | None:
        assignee_value: Any = None
        assignee_was_requested = False
        for field in (
            "assigned_to",
            "assigned_to_id",
            "assigned_user",
            "assigned_user_id",
            "assignee",
            "assignee_id",
            "owner_user_id",
        ):
            if self._normalize_text(draft.get(field)):
                assignee_value = draft[field]
                assignee_was_requested = True
                break
        if isinstance(assignee_value, dict):
            for field in ("id", "user_id", "pk"):
                if self._normalize_text(assignee_value.get(field)):
                    assignee_value = assignee_value[field]
                    break
            else:
                for field in ("name", "display_name", "username", "email"):
                    if self._normalize_text(assignee_value.get(field)):
                        assignee_value = assignee_value[field]
                        break

        for field in (
            "assigned_to_name",
            "assigned_user_name",
            "assignee_name",
            "owner_name",
        ):
            if not self._normalize_text(assignee_value) and self._normalize_text(
                draft.get(field)
            ):
                assignee_value = draft[field]
                assignee_was_requested = True
                break

        normalized = re.sub(r"\s+", " ", self._normalize_text(assignee_value))
        if not normalized:
            return None
        if normalized.casefold() in {"none", "null", "unassigned"}:
            return None
        if normalized.casefold() in {"me", "myself", "self"}:
            if FamilyMembership.objects.filter(
                family=family,
                user=approved_by,
                is_active=True,
            ).exists():
                return approved_by

        id_match = re.fullmatch(r"(?:user:)?(\d+)", normalized, flags=re.IGNORECASE)
        if id_match:
            user = (
                User.objects.filter(
                    id=int(id_match.group(1)),
                    family_memberships__family=family,
                    family_memberships__is_active=True,
                )
                .distinct()
                .first()
            )
            if user is not None:
                return user

        lookup = normalized.casefold()
        members = (
            User.objects.filter(
                family_memberships__family=family,
                family_memberships__is_active=True,
            )
            .distinct()
            .order_by("first_name", "last_name", "username")
        )
        matches: list[User] = []
        for user in members:
            names = {
                user.username,
                user.email,
                user.first_name,
                user.get_full_name(),
            }
            if lookup in {
                re.sub(r"\s+", " ", self._normalize_text(name)).casefold()
                for name in names
            }:
                matches.append(user)
        if len(matches) == 1:
            return matches[0]
        if assignee_was_requested:
            raise ValueError("Task assignee was not found in this family.")
        return None

