    def read_message_attachments(
        self,
        message: FamilyAgentMessage | None,
    ) -> list[dict[str, Any]]:
        if message is None:
            return []

        return [
            {
                "id": str(attachment.id),
                "kind": attachment.kind,
                "original_filename": attachment.original_filename,
                "mime_type": attachment.mime_type,
                "file_size": attachment.file_size,
                "width": attachment.width,
                "height": attachment.height,
                "analysis_status": attachment.analysis_status,
                "analysis": attachment.analysis_json or {},
            }
            for attachment in message.attachments.order_by(
                "display_order", "created_at"
            )
        ]

    def summarize_message_attachments(
        self,
        message: FamilyAgentMessage | None,
    ) -> str:
        summaries: list[str] = []
        seen_summaries: set[str] = set()
        for attachment in self.read_message_attachments(message):
            analysis = attachment.get("analysis") or {}
            if not isinstance(analysis, dict):
                continue
            summary = str(
                analysis.get("message_summary") or analysis.get("planner_summary") or ""
            ).strip()
            if summary and summary not in seen_summaries:
                seen_summaries.add(summary)
                summaries.append(summary)
        return "\n".join(summaries)

    def read_recent_image_attachments(
        self,
        thread: FamilyAgentThread,
        *,
        limit: int = 8,
    ) -> list[dict[str, Any]]:
