def _serialized_size(payload: Any) -> int:
    try:
        return len(json.dumps(payload, default=str))
    except (TypeError, ValueError):
        return len(str(payload))


def _trim_list_in_place(
    container: dict[str, Any],
    key: str,
    *,
    keep_count: int,
) -> bool:
    value = container.get(key)
    if not isinstance(value, list) or len(value) <= keep_count:
        return False
    omitted = len(value) - keep_count
    trimmed = list(value[:keep_count])
    trimmed.append({"truncated": True, "omitted_count": omitted})
    container[key] = trimmed
    return True


def _apply_context_size_budget(
    context: dict[str, Any], *, max_chars: int
) -> dict[str, Any]:
    """Shrink large list fields in `context` until the JSON form fits `max_chars`.

    Walks the configured trimmable list fields in order, halving each list's
    visible items per pass until the budget is met or fields are exhausted. The
    last item replaced with a `{truncated, omitted_count}` marker so callers
    know to fetch more via tools.
    """
    if max_chars <= 0 or _serialized_size(context) <= max_chars:
        return context

    targets: list[tuple[dict[str, Any], str]] = []
    for key in _CONTEXT_TRIMMABLE_LIST_FIELDS:
        if isinstance(context.get(key), list):
            targets.append((context, key))
    for parent_key, child_key in _CONTEXT_TRIMMABLE_NESTED_LISTS:
        parent = context.get(parent_key)
        if isinstance(parent, dict) and isinstance(parent.get(child_key), list):
            targets.append((parent, child_key))

    if not targets:
        return context

    keep_counts: dict[tuple[int, str], int] = {
        (id(container), key): max(1, len(container[key]) // 2)
        for container, key in targets
    }

    for _ in range(8):
        progress = False
        for container, key in targets:
            keep = keep_counts[(id(container), key)]
            if _trim_list_in_place(container, key, keep_count=keep):
                progress = True
        if _serialized_size(context) <= max_chars:
            return context
        if not progress:
            break
        for container, key in targets:
            keep_counts[(id(container), key)] = max(
                1, keep_counts[(id(container), key)] // 2
            )

    return context


class FamilyPlannerToolAdapter:
    def __init__(
        self,
        *,
        scheduling_provider: CalendlySchedulingProvider | None = None,
        google_maps_grounding_client: GoogleMapsGroundingClient | None = None,
    ) -> None:
        self.participation_resolver = TripParticipationResolver()
        self.scheduling_provider = scheduling_provider or CalendlySchedulingProvider()
        self.google_maps_grounding_client = (
            google_maps_grounding_client or GoogleMapsGroundingClient()
        )

    def _is_group_plan_proposal_type(self, proposal_type: Any) -> bool:
        return is_group_plan_proposal_type(proposal_type)

    def _normalize_text(self, value: Any) -> str:
        return str(value or "").strip()

    def _normalize_group_plan_template(self, value: Any) -> str:
        normalized_value = re.sub(
            r"[^A-Z0-9]+",
            "_",
            self._normalize_text(value).upper(),
        ).strip("_")
        if normalized_value in VALID_GROUP_PLAN_TEMPLATES:
            return normalized_value
        return GROUP_PLAN_TEMPLATE_ALIASES.get(normalized_value, "OTHER")

    def _normalize_group_plan_mode(self, value: Any) -> str:
        normalized_value = self._normalize_text(value).upper()
        if normalized_value in VALID_GROUP_PLAN_MODES:
            return normalized_value
        return "TIME_ONLY"

    def _format_utc_iso(self, value: datetime) -> str:
        return (
            value.astimezone(datetime_timezone.utc).isoformat().replace("+00:00", "Z")
