def normalize_capture_payload(
    *, capture_type: str, raw_text: str = "", raw_payload: dict[str, Any] | None = None
) -> dict[str, Any]:
    payload = dict(raw_payload or {})
    lines = [line.strip() for line in raw_text.splitlines() if line.strip()]
    if "suggested_items" not in payload and lines:
        payload["suggested_items"] = lines
    payload.setdefault("suggested_title", lines[0] if lines else "Inbox item")
    payload.setdefault(
        "suggested_kind",
        "grocery_list" if capture_type == InboxCapture.CaptureType.PHOTO else "task",
    )
    if "preview_text" not in payload:
        if lines:
            payload["preview_text"] = " | ".join(lines[:2])[:140]
        elif capture_type == InboxCapture.CaptureType.PHOTO:
            payload["preview_text"] = "Photo capture ready for review"
        elif capture_type == InboxCapture.CaptureType.EMAIL:
            payload["preview_text"] = "Email capture ready for review"
    return payload


def normalize_desktop_capture_payload(
    *,
    capture_type: str,
    raw_text: str = "",
    raw_payload: dict[str, Any] | None = None,
    source_kind: str = "",
    source_url: str = "",
    source_domain: str = "",
    preview_title: str = "",
    preview_text: str = "",
    preview_price_text: str = "",
    thumbnail_ref: str = "",
    captured_from: str = "",
) -> dict[str, Any]:
    payload = normalize_capture_payload(
        capture_type=capture_type,
        raw_text=raw_text,
        raw_payload=raw_payload,
    )

    if any(
        [
            source_url.strip(),
            source_domain.strip(),
            preview_price_text.strip(),
            thumbnail_ref.strip(),
        ]
    ):
        payload["suggested_kind"] = "grocery_list"

    stable_fields = {
        "source_kind": source_kind.strip(),
        "source_url": source_url.strip(),
        "source_domain": source_domain.strip(),
        "preview_title": preview_title.strip(),
        "preview_text": preview_text.strip()
        or str(payload.get("preview_text") or "").strip(),
        "preview_price_text": preview_price_text.strip(),
        "thumbnail_ref": thumbnail_ref.strip(),
        "captured_from": captured_from.strip(),
    }
    for key, value in stable_fields.items():
        if value:
            payload[key] = value
        else:
            payload.setdefault(key, "")

    if (
        payload["preview_title"]
        and not str(payload.get("suggested_title") or "").strip()
    ):
        payload["suggested_title"] = payload["preview_title"]

    return payload


def get_capture_preview_text(capture: InboxCapture) -> str:
    payload = capture.normalized_payload or {}
    preview_text = payload.get("preview_text")
    if isinstance(preview_text, str) and preview_text.strip():
        return preview_text.strip()

    suggested_title = payload.get("suggested_title")
    if isinstance(suggested_title, str) and suggested_title.strip():
        return suggested_title.strip()

    suggested_tasks = payload.get("suggested_tasks")
    if isinstance(suggested_tasks, list):
        task_titles = [
            str(task.get("title", "")).strip()
            for task in suggested_tasks
            if isinstance(task, dict) and str(task.get("title", "")).strip()
        ]
        if task_titles:
            return ", ".join(task_titles[:3])

    suggested_items = payload.get("suggested_items")
    if isinstance(suggested_items, list):
        item_names = [
            str(item).strip() for item in suggested_items if str(item).strip()
        ]
        if item_names:
            return ", ".join(item_names[:3])

    proposals = payload.get("proposals")
    if isinstance(proposals, list):
        for proposal in proposals:
            if not isinstance(proposal, dict):
                continue
            proposal_title = (
                proposal.get("summary")
                or proposal.get("title")
                or proposal.get("name")
                or proposal.get("suggested_title")
            )
            if str(proposal_title or "").strip():
                return str(proposal_title).strip()

    if capture.raw_text.strip():
        return " | ".join(
            line.strip() for line in capture.raw_text.splitlines() if line.strip()
        )[:140]
    if capture.source_email:
        return capture.source_email
    if capture.capture_type == InboxCapture.CaptureType.PHOTO:
        return "Photo capture ready for review"
    if capture.capture_type == InboxCapture.CaptureType.EMAIL:
        return "Email capture ready for review"
    return "Inbox item ready for review"


def _care_subject_summary(care_subject: Any | None) -> dict[str, Any] | None:
    if care_subject is None:
        return None
    if isinstance(care_subject, User):
        name = care_subject.get_full_name().strip() or care_subject.username
        return {
            "type": "person",
            "id": str(care_subject.id),
            "name": name,
            "profile_picture_url": None,
        }
    if not isinstance(care_subject, Pet):
        return None
    profile_picture_url = None
    picture_name = (
        care_subject.profile_picture.name if care_subject.profile_picture else None
    )
    if picture_name:
        try:
            from events.media_services import MediaStorageService

            profile_picture_url = MediaStorageService.generate_presigned_url(
                picture_name
            )
        except Exception:
            logger.debug("Unable to generate pet profile picture URL", exc_info=True)
    return {
        "type": "pet",
        "id": str(care_subject.id),
        "name": care_subject.name,
        "animal_type": care_subject.animal_type,
        "profile_picture_url": profile_picture_url,
